<script lang="ts">import {onMount} from 'svelte';import {base} from '$app/paths';let theme=$state('system');let ready=$state(false);let menu:HTMLDetailsElement;onMount(()=>{theme=document.documentElement.dataset.themePreference||'system';ready=true;});function change(){(window as any).fedrampTheme?.set(theme);}function close(event:KeyboardEvent){if(event.key==='Escape'&&menu?.open){menu.open=false;menu.querySelector('summary')?.focus();}}</script><svelte:window onkeydown={close}/><header class="site-top"><a class="brand" href={base+'/'} aria-label="FedRAMP home page"><img class="logo-light" src={base+'/fedramp-logo.svg'} alt="FedRAMP" width="158" height="48"/><img class="logo-dark" src={base+'/fedramp-logo-inverse.svg'} alt="FedRAMP" width="158" height="48"/></a><div class="utility"><label class="theme-label" hidden={!ready}><span>Appearance</span><select aria-label="Appearance" bind:value={theme} onchange={change}><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></label><details class="menu" bind:this={menu}><summary>Menu <svg class="icon" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 8h16M4 16h16" stroke="currentColor" stroke-width="1.5"/></svg></summary><nav class="menu-links" aria-label="Main navigation"><a href="#providers" onclick={()=>menu.open=false}>Cloud service providers</a><a href="#agencies" onclick={()=>menu.open=false}>Federal agencies</a><a href={base+'/marketplace/'}>Marketplace</a><a href={base+'/rfcs/'}>Public comment</a><a href="https://www.fedramp.gov/2026/">Rules and guidance</a><a href="https://www.fedramp.gov/legacy/">Legacy resources</a><a href="https://www.fedramp.gov/join/">Join the community</a></nav></details></div></header>